import { describe, it, expect, beforeEach } from 'vitest'
import app from '@/app.js'
import { db } from '@/db/index.js'
import { sales, saleLineItems, payments, paymentAllocations, stockMovements, parts, vatRates, sequences } from '@/db/schema.js'
import { eq, count as drizzleCount } from 'drizzle-orm'

// Type definitions for API responses
type SaleResponse = {
  sale: Record<string, unknown>
  payment: Record<string, unknown>
  lineItems: Record<string, unknown>[]
}

type SalesListResponse = {
  sales: Record<string, unknown>[]
  total: number
}

type SaleDetailResponse = {
  sale: Record<string, unknown>
  lineItems: Record<string, unknown>[]
  payments: Record<string, unknown>[]
  stockMovements: Record<string, unknown>[]
}

type VoidErrorResponse = {
  error: string
  code?: 'NOT_FOUND' | 'ALREADY_VOIDED' | 'INTERNAL_ERROR'
}

describe('Sales Routes — Integration Tests (consolidated sale.service.ts)', () => {
  // Helper to reset all relevant tables between tests
  async function resetTables() {
    await db.delete(stockMovements)
    await db.delete(paymentAllocations)
    await db.delete(payments)
    await db.delete(saleLineItems)
    await db.delete(sales)
    await db.delete(sequences)
    await db.delete(parts)
    await db.delete(vatRates)
  }

  beforeEach(async () => {
    await resetTables()
  })

  // ---------------------------------------------------------------------------
  // POST /api/sales — Create a direct sale
  // ---------------------------------------------------------------------------
  describe('POST /api/sales', () => {
    it('should create a complete sale and return all entity types (tracer bullet)', async () => {
      // Seed data: VAT rate and parts with stock
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })
      await db.insert(parts).values([
        { id: 'p1', barcode: 'BAR-001', name: 'Bearing 6205', priceNet: 1000 },
        { id: 'p2', barcode: 'BAR-002', name: 'Chain Ring 50T', priceNet: 3000 }
      ])
      await db.insert(stockMovements).values([
        { id: 'm1', partId: 'p1', quantityDelta: 10, reason: 'manual_correction' },
        { id: 'm2', partId: 'p2', quantityDelta: 5, reason: 'manual_correction' }
      ])

      // Create sale request
      const body = {
        paymentMethod: 'cash',
        lineItems: [
          { partId: 'p1', quantity: 2, unitPriceNet: 1000, vatRateId: 'vat-standard', description: 'Bearing 6205' },
          { partId: 'p2', quantity: 1, unitPriceNet: 3000, vatRateId: 'vat-standard', description: 'Chain Ring 50T' }
        ]
      }

      const res = await app.request('/api/sales', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })

      expect(res.status).toBe(201)

      const json = await res.json() as SaleResponse
      expect(json.sale).toBeDefined()
      expect(json.payment).toBeDefined()
      expect(json.lineItems).toHaveLength(2)

      // Verify sale header has correct totals: 2×1000=2000 + 1×3000=3000 = 5000 net, VAT=1050, gross=6050
      expect((json.sale as Record<string, unknown>).subtotalNet).toBe(5000)
      expect((json.sale as Record<string, unknown>).vatTotal).toBe(1050)
      expect((json.sale as Record<string, unknown>).totalGross).toBe(6050)

      // Verify sale number format (SA-NNNN)
      expect((json.sale as Record<string, unknown>).saleNumber).toMatch(/^SA-\d{4}$/)

      // Verify payment amount matches gross total
      expect((json.payment as Record<string, unknown>).amount).toBe(6050)
      expect((json.payment as Record<string, unknown>).method).toBe('cash')

      // Verify line items have correct computed totals
      const lines = json.lineItems as Record<string, unknown>[]
      expect(lines[0].lineTotalNet).toBe(2000)
      expect(lines[0].lineTotalVat).toBe(420)
      expect(lines[0].lineTotalGross).toBe(2420)

      // Verify all 5 entity types have correct rows in DB
      const dbSales = await db.select().from(sales)
      const dbLines = await db.select().from(saleLineItems)
      const dbPayments = await db.select().from(payments)
      const dbAllocations = await db.select().from(paymentAllocations)
      const saleData = json.sale as Record<string, unknown>
      const dbMovements = await db.select().from(stockMovements).where(eq(stockMovements.referenceId, saleData.id as string))

      expect(dbSales).toHaveLength(1)
      expect(dbLines).toHaveLength(2)
      expect(dbPayments).toHaveLength(1)
      expect(dbAllocations).toHaveLength(1)
      expect(dbMovements).toHaveLength(2)

      // Verify stock movements have negative deltas (deduction)
      const part1Movement = dbMovements.find((m: { partId: string }) => m.partId === 'p1')
      const part2Movement = dbMovements.find((m: { partId: string }) => m.partId === 'p2')
      expect(part1Movement?.quantityDelta).toBe(-2)
      expect(part2Movement?.quantityDelta).toBe(-1)
    })

    it('should accept optional customerId for known customer sales', async () => {
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })
      await db.insert(parts).values({ id: 'p1', barcode: 'BAR-001', name: 'Bearing 6205', priceNet: 1000 })
      await db.insert(stockMovements).values({ id: 'm1', partId: 'p1', quantityDelta: 10, reason: 'manual_correction' })

      const body = {
        customerId: 'cust-abc-123',
        paymentMethod: 'card',
        lineItems: [
          { partId: 'p1', quantity: 1, unitPriceNet: 1000, vatRateId: 'vat-standard', description: 'Bearing 6205' }
        ]
      }

      const res = await app.request('/api/sales', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })

      expect(res.status).toBe(201)
      const json = await res.json() as SaleResponse
      expect((json.sale as Record<string, unknown>).customerId).toBe('cust-abc-123')
    })

    it('should reject entire sale when any part has insufficient stock (409)', async () => {
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })
      await db.insert(parts).values([
        { id: 'p1', barcode: 'BAR-001', name: 'Bearing 6205', priceNet: 1000 },
        { id: 'p2', barcode: 'BAR-002', name: 'Chain Ring 50T', priceNet: 3000 }
      ])

      // Only 2 bearings in stock, requesting 5
      await db.insert(stockMovements).values([
        { id: 'm1', partId: 'p1', quantityDelta: 2, reason: 'manual_correction' },
        { id: 'm2', partId: 'p2', quantityDelta: 5, reason: 'manual_correction' }
      ])

      const body = {
        paymentMethod: 'cash',
        lineItems: [
          { partId: 'p1', quantity: 5, unitPriceNet: 1000, vatRateId: 'vat-standard', description: 'Bearing 6205' },
          { partId: 'p2', quantity: 1, unitPriceNet: 3000, vatRateId: 'vat-standard', description: 'Chain Ring 50T' }
        ]
      }

      const res = await app.request('/api/sales', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })

      expect(res.status).toBe(409)
      const json = await res.json() as Record<string, unknown>
      expect(json.code).toBe('INSUFFICIENT_STOCK')
      const shortfalls = json.shortfalls as Array<{ partId: string; requested: number; available: number }>
      expect(shortfalls).toBeDefined()
      expect(Array.isArray(shortfalls)).toBe(true)
      expect(shortfalls[0].partId).toBe('p1')
      expect(shortfalls[0].requested).toBe(5)
      expect(shortfalls[0].available).toBe(2)

      // Verify NO partial writes — all tables should be empty
      const [{ count: saleCount }] = await db.select({ count: drizzleCount() }).from(sales)
      const [{ count: lineItemCount }] = await db.select({ count: drizzleCount() }).from(saleLineItems)
      const [{ count: paymentCount }] = await db.select({ count: drizzleCount() }).from(payments)

      expect(saleCount).toBe(0)
      expect(lineItemCount).toBe(0)
      expect(paymentCount).toBe(0)
    })

    it('should reject invalid input with 400 (missing line items)', async () => {
      const body = { paymentMethod: 'cash', lineItems: [] }

      const res = await app.request('/api/sales', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })

      expect(res.status).toBe(400)
      const json = await res.json() as Record<string, unknown>
      expect(json.code).toBe('VALIDATION_ERROR')
    })

    it('should reject invalid payment method with 400', async () => {
      const body = { paymentMethod: 'bitcoin' as const, lineItems: [{ partId: 'p1', quantity: 1, unitPriceNet: 1000, vatRateId: 'vat-std', description: 'Test' }] }

      const res = await app.request('/api/sales', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })

      expect(res.status).toBe(400)
    })

    it('should reject missing required fields with 400', async () => {
      const body = { paymentMethod: 'cash' }

      const res = await app.request('/api/sales', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })

      expect(res.status).toBe(400)
    })

    it('should handle discount on line items (basis points)', async () => {
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })
      await db.insert(parts).values({ id: 'p1', barcode: 'BAR-001', name: 'Bearing 6205', priceNet: 1000 })
      await db.insert(stockMovements).values({ id: 'm1', partId: 'p1', quantityDelta: 10, reason: 'manual_correction' })

      // 10% discount = 1000 basis points on a 1000 cent item, qty=2
      const body = {
        paymentMethod: 'cash',
        lineItems: [
          { partId: 'p1', quantity: 2, unitPriceNet: 1000, vatRateId: 'vat-standard', description: 'Bearing 6205', discountPercent: 1000 }
        ]
      }

      const res = await app.request('/api/sales', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })

      expect(res.status).toBe(201)
      const json = await res.json() as SaleResponse
      // Net per unit after discount: 1000 - (1000 * 1000/10000) = 900
      // Line net total: 2 × 900 = 1800
      // VAT: 1800 × 21% = 378
      // Gross: 1800 + 378 = 2178
      expect((json.sale as Record<string, unknown>).subtotalNet).toBe(1800)
      expect((json.sale as Record<string, unknown>).vatTotal).toBe(378)
      expect((json.sale as Record<string, unknown>).totalGross).toBe(2178)
    })

    it('should handle multiple line items with different VAT rates', async () => {
      await db.insert(vatRates).values([
        { id: 'vat-standard', rate: 2100, description: 'Standard 21%' },
        { id: 'vat-reduced', rate: 600, description: 'Reduced 6%' }
      ])
      await db.insert(parts).values([
        { id: 'p1', barcode: 'BAR-001', name: 'Bearing 6205', priceNet: 1000 },
        { id: 'p2', barcode: 'BAR-002', name: 'Chain Ring 50T', priceNet: 3000 }
      ])
      await db.insert(stockMovements).values([
        { id: 'm1', partId: 'p1', quantityDelta: 10, reason: 'manual_correction' },
        { id: 'm2', partId: 'p2', quantityDelta: 5, reason: 'manual_correction' }
      ])

      const body = {
        paymentMethod: 'cash',
        lineItems: [
          { partId: 'p1', quantity: 1, unitPriceNet: 1000, vatRateId: 'vat-standard', description: 'Bearing 6205' },
          { partId: 'p2', quantity: 1, unitPriceNet: 3000, vatRateId: 'vat-reduced', description: 'Chain Ring 50T' }
        ]
      }

      const res = await app.request('/api/sales', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })

      expect(res.status).toBe(201)
      const json = await res.json() as SaleResponse
      // subtotalNet = 1000 + 3000 = 4000
      // vatTotal = 210 + 180 = 390
      // totalGross = 4000 + 390 = 4390
      expect((json.sale as Record<string, unknown>).subtotalNet).toBe(4000)
      expect((json.sale as Record<string, unknown>).vatTotal).toBe(390)
      expect((json.sale as Record<string, unknown>).totalGross).toBe(4390)
    })

    it('should return sequential sale numbers (SA-0001, SA-0002, ...)', async () => {
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })
      await db.insert(parts).values([
        { id: 'p1', barcode: 'BAR-001', name: 'Bearing 6205', priceNet: 1000 }
      ])
      await db.insert(stockMovements).values({ id: 'm1', partId: 'p1', quantityDelta: 10, reason: 'manual_correction' })

      const body = { paymentMethod: 'cash', lineItems: [{ partId: 'p1', quantity: 1, unitPriceNet: 1000, vatRateId: 'vat-standard', description: 'Bearing 6205' }] }

      const res1 = await app.request('/api/sales', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })
      const json1 = await res1.json() as SaleResponse
      expect((json1.sale as Record<string, unknown>).saleNumber).toBe('SA-0001')

      const res2 = await app.request('/api/sales', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })
      const json2 = await res2.json() as SaleResponse
      expect((json2.sale as Record<string, unknown>).saleNumber).toBe('SA-0002')
    })
  })

  // ---------------------------------------------------------------------------
  // GET /api/sales — List recent sales history
  // ---------------------------------------------------------------------------
  describe('GET /api/sales', () => {
    it('should return empty array when no sales exist', async () => {
      const res = await app.request('/api/sales')

      expect(res.status).toBe(200)
      const json = await res.json() as SalesListResponse
      expect(json.sales).toEqual([])
      expect(json.total).toBe(0)
    })

    it('should return recent sales ordered newest first', async () => {
      // Seed data for creating sales
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })
      await db.insert(parts).values([
        { id: 'p1', barcode: 'BAR-001', name: 'Bearing 6205', priceNet: 1000 },
        { id: 'p2', barcode: 'BAR-002', name: 'Chain Ring 50T', priceNet: 3000 }
      ])
      await db.insert(stockMovements).values([
        { id: 'm1', partId: 'p1', quantityDelta: 10, reason: 'manual_correction' },
        { id: 'm2', partId: 'p2', quantityDelta: 5, reason: 'manual_correction' }
      ])

      // Create two sales with a small delay to ensure different timestamps
      const body1 = { paymentMethod: 'cash', lineItems: [{ partId: 'p1', quantity: 1, unitPriceNet: 1000, vatRateId: 'vat-standard', description: 'Bearing 6205' }] }
      await app.request('/api/sales', { method: 'POST', body: JSON.stringify(body1), headers: { 'Content-Type': 'application/json' } })

      await new Promise(r => setTimeout(r, 10))

      const body2 = { paymentMethod: 'card', lineItems: [{ partId: 'p2', quantity: 1, unitPriceNet: 3000, vatRateId: 'vat-standard', description: 'Chain Ring 50T' }] }
      await app.request('/api/sales', { method: 'POST', body: JSON.stringify(body2), headers: { 'Content-Type': 'application/json' } })

      const res = await app.request('/api/sales')

      expect(res.status).toBe(200)
      const json = await res.json() as SalesListResponse
      expect(json.sales).toHaveLength(2)
      expect(json.total).toBe(2)

      // Verify newest first ordering (second sale should be first in list)
      expect((json.sales[0] as Record<string, string>).saleNumber).toBe('SA-0002')
      expect((json.sales[1] as Record<string, string>).saleNumber).toBe('SA-0001')
    })

    it('should respect limit query parameter', async () => {
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })
      await db.insert(parts).values([
        { id: 'p1', barcode: 'BAR-001', name: 'Bearing 6205', priceNet: 1000 },
        { id: 'p2', barcode: 'BAR-002', name: 'Chain Ring 50T', priceNet: 3000 }
      ])
      await db.insert(stockMovements).values([
        { id: 'm1', partId: 'p1', quantityDelta: 10, reason: 'manual_correction' },
        { id: 'm2', partId: 'p2', quantityDelta: 5, reason: 'manual_correction' }
      ])

      // Create two sales
      const body1 = { paymentMethod: 'cash', lineItems: [{ partId: 'p1', quantity: 1, unitPriceNet: 1000, vatRateId: 'vat-standard', description: 'Bearing 6205' }] }
      await app.request('/api/sales', { method: 'POST', body: JSON.stringify(body1), headers: { 'Content-Type': 'application/json' } })

      const body2 = { paymentMethod: 'card', lineItems: [{ partId: 'p2', quantity: 1, unitPriceNet: 3000, vatRateId: 'vat-standard', description: 'Chain Ring 50T' }] }
      await app.request('/api/sales', { method: 'POST', body: JSON.stringify(body2), headers: { 'Content-Type': 'application/json' } })

      const res = await app.request('/api/sales?limit=1')

      expect(res.status).toBe(200)
      const json = await res.json() as SalesListResponse
      // Limit applies to returned array but total should still be 2
      expect(json.sales).toHaveLength(1)
      expect(json.total).toBe(2)
    })
  })

  // ---------------------------------------------------------------------------
  // GET /api/sales/:id — Get a single sale with full details
  // ---------------------------------------------------------------------------
  describe('GET /api/sales/:id', () => {
    it('should return 404 for non-existent sale', async () => {
      const res = await app.request('/api/sales/nonexistent-id')

      expect(res.status).toBe(404)
      const json = await res.json() as VoidErrorResponse
      expect(json.code).toBe('NOT_FOUND')
    })

    it('should return full sale details including lines, payments, and stock movements', async () => {
      // Seed data
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })
      await db.insert(parts).values([
        { id: 'p1', barcode: 'BAR-001', name: 'Bearing 6205', priceNet: 1000 }
      ])
      await db.insert(stockMovements).values({ id: 'm1', partId: 'p1', quantityDelta: 10, reason: 'manual_correction' })

      // Create a sale
      const body = { paymentMethod: 'cash', lineItems: [{ partId: 'p1', quantity: 2, unitPriceNet: 1000, vatRateId: 'vat-standard', description: 'Bearing 6205' }] }
      const createRes = await app.request('/api/sales', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })
      const createJson = await createRes.json() as SaleResponse
      const saleId = (createJson.sale as Record<string, unknown>).id as string

      // Fetch the sale detail
      const res = await app.request(`/api/sales/${saleId}`)

      expect(res.status).toBe(200)
      const json = await res.json() as SaleDetailResponse
      expect((json.sale as Record<string, unknown>).id).toBe(saleId)
      expect(json.lineItems).toHaveLength(1)
      expect(json.payments).toHaveLength(1)
      expect(json.stockMovements).toHaveLength(1)

      // Verify stock movement is negative (deduction)
      const movement = json.stockMovements[0] as Record<string, unknown>
      expect(movement.quantityDelta).toBe(-2)
    })
  })

  // ---------------------------------------------------------------------------
  // PATCH /api/sales/:id/void — Void a completed sale
  // ---------------------------------------------------------------------------
  describe('PATCH /api/sales/:id/void', () => {
    it('should void a completed sale and return updated status', async () => {
      // Seed data
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })
      await db.insert(parts).values([
        { id: 'p1', barcode: 'BAR-001', name: 'Bearing 6205', priceNet: 1000 }
      ])
      await db.insert(stockMovements).values({ id: 'm1', partId: 'p1', quantityDelta: 10, reason: 'manual_correction' })

      // Create a sale first
      const body = { paymentMethod: 'cash', lineItems: [{ partId: 'p1', quantity: 1, unitPriceNet: 1000, vatRateId: 'vat-standard', description: 'Bearing 6205' }] }
      const createRes = await app.request('/api/sales', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })
      const createJson = await createRes.json() as SaleResponse
      const saleId = (createJson.sale as Record<string, unknown>).id as string

      // Void the sale
      const res = await app.request(`/api/sales/${saleId}/void`, { method: 'PATCH' })

      expect(res.status).toBe(200)
      const json = await res.json() as Record<string, unknown>
      expect((json.sale as Record<string, unknown>).status).toBe('voided')
    })

    it('should return 404 for non-existent sale', async () => {
      const res = await app.request('/api/sales/nonexistent-id/void', { method: 'PATCH' })

      expect(res.status).toBe(404)
      const json = await res.json() as VoidErrorResponse
      expect(json.code).toBe('NOT_FOUND')
    })

    it('should return 409 when trying to void an already-voided sale', async () => {
      // Seed data
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })
      await db.insert(parts).values([
        { id: 'p1', barcode: 'BAR-001', name: 'Bearing 6205', priceNet: 1000 }
      ])
      await db.insert(stockMovements).values({ id: 'm1', partId: 'p1', quantityDelta: 10, reason: 'manual_correction' })

      // Create and void a sale
      const body = { paymentMethod: 'cash', lineItems: [{ partId: 'p1', quantity: 1, unitPriceNet: 1000, vatRateId: 'vat-standard', description: 'Bearing 6205' }] }
      const createRes = await app.request('/api/sales', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })
      const createJson = await createRes.json() as SaleResponse
      const saleId = (createJson.sale as Record<string, unknown>).id as string

      // First void — should succeed
      const res1 = await app.request(`/api/sales/${saleId}/void`, { method: 'PATCH' })
      expect(res1.status).toBe(200)

      // Second void — should fail with 409
      const res2 = await app.request(`/api/sales/${saleId}/void`, { method: 'PATCH' })

      expect(res2.status).toBe(409)
      const json = await res2.json() as VoidErrorResponse
      expect(json.code).toBe('ALREADY_VOIDED')
    })

    it('should only change sale status — no stock movement or payment side effects (R13)', async () => {
      // Seed data
      await db.insert(vatRates).values({ id: 'vat-standard', rate: 2100, description: 'Standard 21%' })
      await db.insert(parts).values([
        { id: 'p1', barcode: 'BAR-001', name: 'Bearing 6205', priceNet: 1000 }
      ])
      await db.insert(stockMovements).values({ id: 'm1', partId: 'p1', quantityDelta: 10, reason: 'manual_correction' })

      // Create a sale with two line items
      const body = {
        paymentMethod: 'cash',
        lineItems: [
          { partId: 'p1', quantity: 2, unitPriceNet: 1000, vatRateId: 'vat-standard', description: 'Bearing 6205' }
        ]
      }
      const createRes = await app.request('/api/sales', { method: 'POST', body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } })
      const createJson = await createRes.json() as SaleResponse
      const saleId = (createJson.sale as Record<string, unknown>).id as string

      // Capture pre-void state
      const preMovementsCount = (await db.select({ count: drizzleCount() }).from(stockMovements).where(eq(stockMovements.referenceType, 'sale')))[0].count
      const prePaymentsCount = (await db.select({ count: drizzleCount() }).from(payments))[0].count
      const preAllocationsCount = (await db.select({ count: drizzleCount() }).from(paymentAllocations))[0].count

      // Void the sale
      const res = await app.request(`/api/sales/${saleId}/void`, { method: 'PATCH' })
      expect(res.status).toBe(200)

      // Verify only status changed — no new stock movements, payments, or allocations
      const postMovementsCount = (await db.select({ count: drizzleCount() }).from(stockMovements).where(eq(stockMovements.referenceType, 'sale')))[0].count
      const postPaymentsCount = (await db.select({ count: drizzleCount() }).from(payments))[0].count
      const postAllocationsCount = (await db.select({ count: drizzleCount() }).from(paymentAllocations))[0].count

      expect(postMovementsCount).toBe(preMovementsCount)
      expect(postPaymentsCount).toBe(prePaymentsCount)
      expect(postAllocationsCount).toBe(preAllocationsCount)

      // Verify sale status is voided but other fields unchanged
      const json = await res.json() as Record<string, unknown>
      expect((json.sale as Record<string, unknown>).status).toBe('voided')
      expect(Number((json.sale as Record<string, unknown>).totalGross)).toBe(2420) // gross total unchanged
    })
  })
})

/**
 * Quote feature API client.
 */

import type {
  QuoteDetail,
  QuoteListItem,
  QuoteLineItem,
  CreateQuoteFormData,
  CreateLineItemData,
} from './types.js'

// ---------------------------------------------------------------------------
// Types for request/response shapes
// ---------------------------------------------------------------------------

export interface QuotesListResponse {
  quotes: QuoteListItem[]
  total: number
}

interface UpdateQuoteInput {
  customerId?: string | null
  notes?: string
}

interface UpdateLineItemInput {
  lineType: 'part' | 'labor' | 'bicycle'
  description?: string
  quantity?: number
  unitPriceNet?: number
  vatRateId?: string
  discountPercent?: number | null
  partId?: string | null
  laborServiceId?: string | null
  bicycleId?: string | null
