/**
 * Product Finder — Import service for DST products into local catalog.
 *
 * Handles:
 * - Creating new parts from DST search results (quantityOnHand = 0, isActive = true)
 * - Updating existing parts with new pricing/name without touching stock levels
 * - Refreshing supplier product cache on import
 */

import { db } from '@/db/index.js'
import { parts, stockMovements, supplierProducts } from '@/db/schema.js'
import type { ImportRequest, ImportResult } from '../types.js'
import type { NewStockMovement } from '@/db/schema.js'
import { eq } from 'drizzle-orm'
import crypto from 'crypto'

// ============================================================================
// Configuration
// ============================================================================

/** VAT rate used for net price calculation (21% → divisor 1.21) */
const VAT_DIVISOR = 1.21

// ============================================================================
// Part creation & update
// ============================================================================

/**
 * Generate a deterministic ID for a new part based on EAN.
 */
function generatePartId(eanUpc: string): string {
  // Use the first 16 chars of the EAN as the part ID (EAN-13 = 13 digits)
  return `part-${eanUpc.slice(0, 13)}`
}

/**
 * Generate a deterministic ID for a supplier product cache entry.
 */
function generateSupplierProductId(eanUpc: string, supplierName: string): string {
  const hash = crypto.createHash('sha256').update(`${eanUpc}|${supplierName}`).digest('hex').slice(0, 16)
  return `sp-${hash}`
}

/**
 * Check if a part already exists by barcode (EAN).
 */
async function findPartByBarcode(eanUpc: string): Promise<{ id: string } | null> {
  const result = await db.select({ id: parts.id })
    .from(parts)
    .where(eq(parts.barcode, eanUpc))
    .limit(1)

  return result[0] ?? null
}

/**
 * Create a new part from supplier import data.
 */
async function createPart(request: ImportRequest): Promise<string> {
  const partId = generatePartId(request.eanUpc)

  await db.insert(parts).values({
    id: partId,
    barcode: request.eanUpc,
    name: request.name.trim(),
    priceNet: request.sellPrice,
    costPrice: request.costPrice,
    quantityOnHand: request.quantityOnHand ?? 0,
    isActive: true
  })

  // Create initial stock movement so checkout validation works.
  // Only when there's actual stock — zero-delta movements add noise.
  const quantity = request.quantityOnHand ?? 0
  if (quantity > 0) {
    await repoCreateStockMovement(partId, quantity)
  }

  return partId
}

/**
 * Create a stock movement record for inventory tracking.
 */
async function repoCreateStockMovement(
  partId: string,
  quantityDelta: number
): Promise<void> {
  await db
    .insert(stockMovements)
    .values({
      id: crypto.randomUUID(),
      partId,
      quantityDelta,
      reason: 'order_receive',
      referenceType: null,
      referenceId: null,
      createdAt: Date.now()
    } as NewStockMovement)
}

/**
 * Update an existing part with new pricing and name.
 * Stock levels (quantityOnHand) are preserved — never modified during import.
 */
async function updatePart(partId: string, request: ImportRequest): Promise<void> {
  await db.update(parts)
    .set({
      name: request.name.trim(),
      priceNet: request.sellPrice,
      costPrice: request.costPrice
    })
    .where(eq(parts.id, partId))
}

// ============================================================================
// Supplier product cache refresh
// ============================================================================

/**
 * Refresh the supplier product cache entry for this EAN + supplier.
 * Upserts: creates a new entry if none exists (e.g., import without prior sync),
 * or updates existing data with current import details.
 */
async function refreshSupplierCache(request: ImportRequest): Promise<void> {
  const now = new Date()
  const rawJson = JSON.stringify({
    ean_upc: request.eanUpc,
    name: request.name.trim(),
    recommended_retailprice: Math.round(request.sellPrice * VAT_DIVISOR),
    gross_purchase_price: Math.round(request.costPrice * VAT_DIVISOR),
    supplierName: request.supplierName
  })

  await db.insert(supplierProducts).values({
    id: generateSupplierProductId(request.eanUpc, request.supplierName),
    eanUpc: request.eanUpc,
    rawJson,
    supplierName: request.supplierName,
    searchedAt: now
  }).onConflictDoUpdate({
    target: [supplierProducts.eanUpc, supplierProducts.supplierName],
    set: {
      rawJson,
      supplierName: request.supplierName,
      searchedAt: now
    }
  })
}

// ============================================================================
// Public import API
// ============================================================================

/**
 * Import a product into the local catalog.
 * Creates new parts or updates existing ones (preserving stock levels).
 */
export async function importProduct(request: ImportRequest): Promise<ImportResult> {
  // Validate input
  if (!request.eanUpc || !request.name.trim()) {
    return { success: false, action: 'updated', message: 'EAN and name are required' }
  }

  const eanUpc = request.eanUpc.trim()

  // Check if part already exists by barcode (EAN)
  const existingPart = await findPartByBarcode(eanUpc)

  let action: 'created' | 'updated'
  let partId: string

  if (existingPart) {
    // Update existing part — preserve stock levels
    await updatePart(existingPart.id, request)
    action = 'updated'
    partId = existingPart.id
  } else {
    // Create new part with optional initial stock
    partId = await createPart(request)
    action = 'created'
  }

  // Refresh supplier product cache
  await refreshSupplierCache(request)

  return {
    success: true,
    partId,
    action,
    message: action === 'created'
      ? `New part created with barcode ${eanUpc}`
      : `Part updated — stock levels preserved`
  }
}

