    if (name === 'QuoteLineItemNotFoundError') {
      return c.json({ error: message, code: 'NOT_FOUND' }, 404)
    }

    console.error('[PATCH /quotes/:quoteId/lines/:lineId] Unexpected error:', err)
    return c.json({ error: message, code: 'INTERNAL_ERROR' }, 500)
  }
})

