      })

      expect(res.status).toBe(200)
      const json = await res.json() as Record<string, unknown>
      expect((json.order as Record<string, unknown>).status).toBe('received')
    })

    it('should reject invalid transition (e.g. received → pending) with 409', async () => {
      // Create and move to received
      const createRes = await app.request('/api/supplier-orders', {
        method: 'POST',
        body: JSON.stringify({ supplierName: 'dst', items: [{ eanUpc: '8712345678901', quantityOrdered: 2 }] }),
        headers: { 'Content-Type': 'application/json' }
      })
      const createJson = await createRes.json() as CreateSupplierOrderResponse
      const orderId = (createJson.order as Record<string, unknown>).id as string

      // Skip to received via direct DB update for this test
      await db.update(supplierOrders).set({ status: 'received' }).where(eq(supplierOrders.id, orderId))

      // Try to go back to pending — should fail
      const res = await app.request(`/api/supplier-orders/${orderId}/status`, {
        method: 'PATCH',
        body: JSON.stringify({ status: 'pending' }),
        headers: { 'Content-Type': 'application/json' }
