/**
 * Quotes Page — List view with status filter and "New Quote" button.
 */

import { useCallback, useState } from 'react'
import toast from 'react-hot-toast'
import { useNavigate } from 'react-router-dom'
import type { QuoteStatus as SharedQuoteStatus } from '@shared/validations'
import { CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { CreateQuoteDialog } from './CreateQuoteForm'
import { getQuotes, type QuotesListResponse } from '../api.js'
import { LINE_TYPE_LABELS, type QuoteListItem } from '../types.js'

// ---------------------------------------------------------------------------
// Component — Status Badge
// ---------------------------------------------------------------------------

function StatusBadge({ status }: { status: SharedQuoteStatus }) {
  const colorMap: Record<SharedQuoteStatus, string> = {
    draft: 'bg-gray-100 text-gray-800 dark:bg-gray-900/30 dark:text-gray-400',
    sent: 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400',
    converted: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400',
    rejected: 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400',
  }

  return (
    <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${colorMap[status] || colorMap.draft}`}>
      {LINE_TYPE_LABELS[status as keyof typeof LINE_TYPE_LABELS] ?? status}
    </span>
  )
}

// ---------------------------------------------------------------------------
// Component — Customer Name Helper
// ---------------------------------------------------------------------------

function getCustomerName(customerId: string | null): string {
  if (!customerId) return 'Walk-in'
  return `Customer ${customerId.slice(0, 8)}...`
}

// ---------------------------------------------------------------------------
// Component — Date Formatter
// ---------------------------------------------------------------------------

function formatDate(epochMs: number): string {
  return new Date(epochMs).toLocaleDateString('en-IE', {
    year: 'numeric',
    month: 'short',
    day: '2-digit',
  })
}

// ---------------------------------------------------------------------------
// Component — Quotes Page
// ---------------------------------------------------------------------------

export function QuotesPage() {
  const navigate = useNavigate()
  const [quotes, setQuotes] = useState<QuoteListItem[]>([])
  const [totalPages, setTotalPages] = useState(1)
  const [currentPage, setCurrentPage] = useState(1)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [statusFilter, setStatusFilter] = useState<SharedQuoteStatus | ''>('')

  // Dialog state for creating new quotes
  const [showNewDialog, setShowNewDialog] = useState(false)

  // Fetch quotes list
  const fetchQuotes = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const data: QuotesListResponse = await getQuotes(statusFilter || undefined)
      setQuotes(data.quotes)
      setTotalPages(Math.ceil(data.total / 20))
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load quotes')
    } finally {
      setLoading(false)
    }
  }, [statusFilter])

  // Initial fetch and re-fetch on filter/page change
  useState(() => {
    fetchQuotes()
  })

  // Handle "New Quote" button click -> opens modal dialog
  const handleNewQuote = () => {
    setShowNewDialog(true)
  }

  // Handle row click to view detail
  const handleViewQuote = (id: string) => {
    navigate(`/quotes/${id}`)
  }

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <CardHeader className="pb-2 px-6 pt-4">
        <div className="flex items-center justify-between">
          <CardTitle className="text-xl">Quotes</CardTitle>
          <Button onClick={handleNewQuote}>New Quote</Button>
        </div>
      </CardHeader>

      {/* Content */}
      <CardContent className="px-6 pb-6 flex-1 overflow-auto">
        {error && (
          <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded text-sm text-red-700 dark:bg-red-900/20 dark:border-red-800 dark:text-red-400">
            <p className="font-medium">Error loading quotes</p>
            <p>{error}</p>
          </div>
        )}

        {loading ? (
          <div className="flex items-center justify-center py-16 text-muted-foreground">
            Loading quotes...
          </div>
        ) : quotes.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16 text-muted-foreground gap-2">
            <p className="text-lg font-medium">No quotes yet</p>
            <p className="text-sm">Create your first quote to get started.</p>
            <Button onClick={handleNewQuote} className="mt-2">
              New Quote
            </Button>
          </div>
        ) : (
          <>
            {/* Summary */}
            <div className="mb-4 text-sm text-muted-foreground flex items-center justify-between">
              <span>Showing {quotes.length} of {totalPages * 20} total quote(s)</span>

              {/* Status filter */}
              <div className="flex items-center gap-2">
                <label htmlFor="statusFilter" className="text-xs text-muted-foreground">Status:</label>
                <select
                  id="statusFilter"
                  value={statusFilter}
                  onChange={(e) => {
                    setStatusFilter(e.target.value as SharedQuoteStatus | '')
                    setCurrentPage(1)
                  }}
                  className="rounded-md border border-input bg-background px-2 py-1 text-sm focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/20"
                >
                  <option value="">All Statuses</option>
                  <option value="draft">Draft</option>
                  <option value="sent">Sent</option>
                  <option value="converted">Converted</option>
                  <option value="rejected">Rejected</option>
                </select>
              </div>
            </div>

            {/* Quotes table */}
            <div className="border rounded-lg overflow-hidden">
              <table className="w-full text-sm">
                <thead>
                  <tr className="bg-muted/50 border-b">
                    <th className="text-left px-4 py-2 font-medium text-muted-foreground">Quote #</th>
                    <th className="text-center px-4 py-2 font-medium text-muted-foreground">Status</th>
                    <th className="text-left px-4 py-2 font-medium text-muted-foreground">Customer</th>
                    <th className="text-left px-4 py-2 font-medium text-muted-foreground">Created</th>
                    <th className="text-center px-4 py-2 font-medium text-muted-foreground">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {quotes.map((quote) => (
                    <tr key={quote.id} className="border-b last:border-b-0 hover:bg-muted/30 transition-colors">
                      <td className="px-4 py-2 font-mono text-xs">{quote.quoteNumber}</td>
                      <td className="px-4 py-2 text-center">
                        <StatusBadge status={quote.status} />
                      </td>
                      <td className="px-4 py-2">{getCustomerName(quote.customerId)}</td>
                      <td className="px-4 py-2 whitespace-nowrap">{formatDate(quote.createdAt)}</td>
                      <td className="px-4 py-2 text-center">
                        {quote.status === 'draft' ? (
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => handleViewQuote(quote.id)}
                            className="text-blue-600 hover:text-blue-700 dark:text-blue-400 dark:hover:text-blue-300 h-8 px-2 text-xs"
                          >
                            View
                          </Button>
                        ) : (
                          <span className="text-muted-foreground text-xs">—</span>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* Pagination */}
            {totalPages > 1 && (
              <div className="flex items-center justify-between mt-4">
                <p className="text-sm text-muted-foreground">
                  Page {currentPage} of {totalPages}
                </p>
                <div className="flex gap-2">
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setCurrentPage(Math.max(1, currentPage - 1))}
                    disabled={currentPage === 1}
                  >
                    Previous
                  </Button>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setCurrentPage(Math.min(totalPages, currentPage + 1))}
                    disabled={currentPage === totalPages}
                  >
                    Next
                  </Button>
                </div>
              </div>
            )}
          </>
        )}

        {/* New Quote Dialog Modal */}
        <CreateQuoteDialog
          isOpen={showNewDialog}
          onClose={() => setShowNewDialog(false)}
          onSuccess={(quoteId) => {
            toast.success('Quote created successfully')
            fetchQuotes()
            navigate(`/quotes/${quoteId}`)
          }}
        />
      </CardContent>
    </div>
  )
}

