/**
 * Supplier Orders Page — List view with filters, create order dialog, and receive flow.
 */

import { useCallback, useState } from 'react'
import toast from 'react-hot-toast'
import type { SupplierOrderStatus } from '../types.js'
import { SUPPLIER_ORDER_STATUS_COLORS, SUPPLIER_NAMES, SUPPLIER_LABELS } from '../types.js'
import {
  getSupplierOrders,
  createSupplierOrder,
  updateSupplierOrderStatus,
  receiveSupplierOrder,
  type SupplierOrdersListResponse,
} from '../api.js'
import type { SupplierOrderListItem, SupplierOrderLine, OrderItemInput } from '../types.js'
import { CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'

// ---------------------------------------------------------------------------
// Component — Status Badge
// ---------------------------------------------------------------------------

function StatusBadge({ status }: { status: SupplierOrderStatus }) {
  return (
    <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${SUPPLIER_ORDER_STATUS_COLORS[status]}`}>
      {status.charAt(0).toUpperCase() + status.slice(1)}
    </span>
  )
}

// ---------------------------------------------------------------------------
// Component — Date Formatter
// ---------------------------------------------------------------------------

function formatDate(epochMs: number | null): string {
  if (!epochMs) return '—'
  return new Date(epochMs).toLocaleDateString('en-IE', {
    year: 'numeric',
    month: 'short',
    day: '2-digit',
  })
}

// ---------------------------------------------------------------------------
// Component — Supplier Name Label
// ---------------------------------------------------------------------------

function supplierLabel(name: string): string {
  return SUPPLIER_LABELS[name as keyof typeof SUPPLIER_LABELS] ?? name
}

// ---------------------------------------------------------------------------
// Component — Create Order Dialog
// ---------------------------------------------------------------------------

interface CreateOrderDialogProps {
  isOpen: boolean
  onClose: () => void
  onSuccess: (orderId: string) => void
}

function CreateOrderDialog({ isOpen, onClose, onSuccess }: CreateOrderDialogProps) {
  const [supplierName, setSupplierName] = useState('dst')
  const [items, setItems] = useState<OrderItemInput[]>([{ eanUpc: '', quantityOrdered: 1 }])
  const [loading, setLoading] = useState(false)

  const addItem = () => {
    setItems([...items, { eanUpc: '', quantityOrdered: 1 }])
  }

  const removeItem = (index: number) => {
    if (items.length <= 1) return // keep at least one row
    setItems(items.filter((_, i) => i !== index))
  }

  const updateItem = (index: number, field: keyof OrderItemInput, value: string | number) => {
    const updated = [...items]
    updated[index] = { ...updated[index], [field]: value }
    setItems(updated)
  }

  const handleSubmit = async () => {
    // Filter out empty EAN rows
    const validItems = items.filter(item => item.eanUpc.trim() !== '')
    if (validItems.length === 0) {
      toast.error('Add at least one item with a valid EAN')
      return
    }

    setLoading(true)
    try {
      const result = await createSupplierOrder({ supplierName, items: validItems })
      toast.success(`Order created — ${validItems.length} line(s)`)
      onSuccess(result.order.id)
      // Reset form
      setItems([{ eanUpc: '', quantityOrdered: 1 }])
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to create order')
    } finally {
      setLoading(false)
    }
  }

  const handleClose = () => {
    setItems([{ eanUpc: '', quantityOrdered: 1 }])
    onClose()
  }

  return (
    <Dialog open={isOpen} onOpenChange={handleClose}>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle>New Supplier Order</DialogTitle>
          <DialogDescription>
            Add items from the supplier catalog. Duplicate EANs will be merged automatically.
          </DialogDescription>
        </DialogHeader>

        {/* Supplier selector */}
        <div className="space-y-4">
          <div>
            <label htmlFor="supplierName" className="text-sm font-medium mb-1 block">Supplier</label>
            <select
              id="supplierName"
              value={supplierName}
              onChange={(e) => setSupplierName(e.target.value)}
              className="w-full rounded-md border border-input bg-background px-3 py-2 text-sm focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/20"
            >
              {SUPPLIER_NAMES.map((name) => (
                <option key={name} value={name}>{supplierLabel(name)}</option>
              ))}
            </select>
          </div>

          {/* Items table */}
          <div>
            <label className="text-sm font-medium mb-1 block">Items</label>
            <div className="space-y-2">
              {items.map((item, index) => (
                <div key={index} className="flex gap-2 items-center">
                  <Input
                    placeholder="EAN / UPC"
                    value={item.eanUpc}
                    onChange={(e) => updateItem(index, 'eanUpc', e.target.value)}
                    className="flex-1 h-9"
                  />
                  <Input
                    type="number"
                    min="1"
                    placeholder="Qty"
                    value={item.quantityOrdered}
                    onChange={(e) => updateItem(index, 'quantityOrdered', parseInt(e.target.value) || 1)}
                    className="w-20 h-9"
                  />
                  {items.length > 1 && (
                    <Button variant="ghost" size="sm" onClick={() => removeItem(index)} className="h-9 w-9 p-0">
                      ✕
                    </Button>
                  )}
                </div>
              ))}
            </div>
          </div>

          <Button variant="outline" size="sm" onClick={addItem} type="button">
            + Add Item
          </Button>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={handleClose}>Cancel</Button>
          <Button onClick={handleSubmit} disabled={loading}>
            {loading ? 'Creating...' : 'Create Order'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

// ---------------------------------------------------------------------------
// Component — Order Detail Panel (with receive flow)
// ---------------------------------------------------------------------------

interface OrderDetailPanelProps {
  orderId: string
  onClose: () => void
  onRefresh: () => void
}

function OrderDetailPanel({ orderId, onClose, onRefresh }: OrderDetailPanelProps) {
  const [order, setOrder] = useState<SupplierOrderListItem | null>(null)
  const [lines, setLines] = useState<SupplierOrderLine[]>([])
  const [loading, setLoading] = useState(true)
  const [receiving, setReceiving] = useState(false)

  // Fetch order detail on mount
  useCallback(async () => {
    try {
      const res = await fetch(`/api/supplier-orders/${orderId}`)
      if (!res.ok) throw new Error('Failed to load order')
      const data = await res.json()
      setOrder(data.order)
      setLines(data.lines)
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to load order')
      onClose()
    } finally {
      setLoading(false)
    }
  }, [orderId, onClose])

  // Initial fetch
  useState(() => {
    fetchDetail()
  })

  async function fetchDetail() {
    try {
      const res = await fetch(`/api/supplier-orders/${orderId}`)
      if (!res.ok) throw new Error('Failed to load order')
      const data = await res.json()
      setOrder(data.order)
      setLines(data.lines)
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to load order')
    }
  }

  // Handle status transition
  async function handleStatusTransition(nextStatus: SupplierOrderStatus) {
    try {
      await updateSupplierOrderStatus(orderId, nextStatus)
      toast.success(`Order marked as ${nextStatus}`)
      fetchDetail()
      onRefresh()
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to update status')
    }
  }

  // Handle receive stock
  async function handleReceive() {
    setReceiving(true)
    try {
      await receiveSupplierOrder(orderId)
      toast.success('Stock received successfully')
      fetchDetail()
      onRefresh()
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to receive stock')
    } finally {
      setReceiving(false)
    }
  }

  if (!order || loading) return null

  // Determine available actions based on status
  const canMarkOrdered = order.status === 'pending'
  const canReceive = order.status === 'ordered'

  // Check for unimported lines (partId is null)
  const hasUnimportedLines = lines.some(line => !line.partId)

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50" onClick={onClose}>
      <div
        className="bg-background border rounded-lg shadow-lg w-full max-w-2xl max-h-[80vh] overflow-auto m-4"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b">
          <div>
            <h2 className="text-lg font-semibold">Order Detail</h2>
            <p className="text-sm text-muted-foreground">{supplierLabel(order.supplierName)}</p>
          </div>
          <Button variant="ghost" size="sm" onClick={onClose}>✕</Button>
        </div>

        {/* Status & Actions */}
        <div className="flex items-center gap-3 p-4 border-b">
          <StatusBadge status={order.status} />
          {canMarkOrdered && (
            <Button size="sm" onClick={() => handleStatusTransition('ordered')}>
              Mark as Ordered
            </Button>
          )}
          {canReceive && !hasUnimportedLines && (
            <Button size="sm" variant="default" onClick={handleReceive} disabled={receiving}>
              {receiving ? 'Receiving...' : 'Receive Stock'}
            </Button>
          )}
          {canReceive && hasUnimportedLines && (
            <span className="text-sm text-amber-600 dark:text-amber-400">
              ⚠ Cannot receive — import unimported items first
            </span>
          )}
        </div>

        {/* Line Items Table */}
        <div className="p-4">
          <h3 className="text-sm font-medium mb-2">Line Items ({lines.length})</h3>
          <div className="border rounded-lg overflow-hidden">
            <table className="w-full text-sm">
              <thead>
                <tr className="bg-muted/50 border-b">
                  <th className="text-left px-3 py-2 font-medium text-muted-foreground">EAN / UPC</th>
                  <th className="text-center px-3 py-2 font-medium text-muted-foreground">Ordered</th>
                  <th className="text-center px-3 py-2 font-medium text-muted-foreground">Received</th>
                  <th className="text-left px-3 py-2 font-medium text-muted-foreground">Status</th>
                </tr>
              </thead>
              <tbody>
                {lines.map((line) => {
                  const isImported = !!line.partId
                  const remaining = line.quantityOrdered - line.quantityReceived
                  return (
                    <tr key={line.id} className="border-b last:border-b-0">
                      <td className="px-3 py-2 font-mono text-xs">{line.eanUpc}</td>
                      <td className="px-3 py-2 text-center">{line.quantityOrdered}</td>
                      <td className="px-3 py-2 text-center">{line.quantityReceived}</td>
                      <td className="px-3 py-2">
                        {!isImported ? (
                          <span className="text-xs text-amber-600 dark:text-amber-400">Not Imported</span>
                        ) : remaining > 0 ? (
                          <span className="text-xs text-blue-600 dark:text-blue-400">{remaining} pending</span>
                        ) : (
                          <span className="text-xs text-green-600 dark:text-green-400">Complete</span>
                        )}
                      </td>
                    </tr>
                  )
                })}
              </tbody>
            </table>
          </div>

          {/* Metadata */}
          <div className="mt-4 text-xs text-muted-foreground space-y-1">
            <p>ID: {order.id}</p>
            <p>Created: {formatDate(order.createdAt)}</p>
            {order.orderedAt && <p>Ordered At: {formatDate(order.orderedAt)}</p>}
            {order.referenceNumber && <p>Reference: {order.referenceNumber}</p>}
          </div>
        </div>
      </div>
    </div>
  )
}

// ---------------------------------------------------------------------------
// Component — Supplier Orders Page (main)
// ---------------------------------------------------------------------------

export function SupplierOrdersPage() {
  const [orders, setOrders] = useState<SupplierOrderListItem[]>([])
  const [total, setTotal] = useState(0)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [statusFilter, setStatusFilter] = useState<SupplierOrderStatus | ''>('')
  const [supplierFilter, setSupplierFilter] = useState('')

  // Dialog state
  const [showCreateDialog, setShowCreateDialog] = useState(false)
  const [selectedOrderId, setSelectedOrderId] = useState<string | null>(null)

  // Fetch orders list
  const fetchOrders = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const data: SupplierOrdersListResponse = await getSupplierOrders({
        statusFilter: statusFilter || undefined,
        supplierName: supplierFilter || undefined,
      })
      setOrders(data.orders)
      setTotal(data.total)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load orders')
    } finally {
      setLoading(false)
    }
  }, [statusFilter, supplierFilter])

  // Initial fetch and re-fetch on filter change
  useState(() => {
    fetchOrders()
  })

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <CardHeader className="pb-2 px-6 pt-4">
        <div className="flex items-center justify-between">
          <CardTitle className="text-xl">Supplier Orders</CardTitle>
          <Button onClick={() => setShowCreateDialog(true)}>New Order</Button>
        </div>
      </CardHeader>

      {/* Content */}
      <CardContent className="px-6 pb-6 flex-1 overflow-auto">
        {error && (
          <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded text-sm text-red-700 dark:bg-red-900/20 dark:border-red-800 dark:text-red-400">
            <p className="font-medium">Error loading orders</p>
            <p>{error}</p>
          </div>
        )}

        {loading ? (
          <div className="flex items-center justify-center py-16 text-muted-foreground">
            Loading supplier orders...
          </div>
        ) : orders.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16 text-muted-foreground gap-2">
            <p className="text-lg font-medium">No supplier orders yet</p>
            <p className="text-sm">Create your first order to start procuring stock.</p>
            <Button onClick={() => setShowCreateDialog(true)} className="mt-2">
              New Order
            </Button>
          </div>
        ) : (
          <>
            {/* Summary & Filters */}
            <div className="mb-4 text-sm text-muted-foreground flex items-center justify-between">
              <span>Showing {orders.length} of {total} total order(s)</span>

              <div className="flex items-center gap-3">
                {/* Supplier filter */}
                <div className="flex items-center gap-2">
                  <label htmlFor="supplierFilter" className="text-xs text-muted-foreground">Supplier:</label>
                  <select
                    id="supplierFilter"
                    value={supplierFilter}
                    onChange={(e) => setSupplierFilter(e.target.value)}
                    className="rounded-md border border-input bg-background px-2 py-1 text-sm focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/20"
                  >
                    <option value="">All Suppliers</option>
                    {SUPPLIER_NAMES.map((name) => (
                      <option key={name} value={name}>{supplierLabel(name)}</option>
                    ))}
                  </select>
                </div>

                {/* Status filter */}
                <div className="flex items-center gap-2">
                  <label htmlFor="statusFilter" className="text-xs text-muted-foreground">Status:</label>
                  <select
                    id="statusFilter"
                    value={statusFilter}
                    onChange={(e) => setStatusFilter(e.target.value as SupplierOrderStatus | '')}
                    className="rounded-md border border-input bg-background px-2 py-1 text-sm focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/20"
                  >
                    <option value="">All Statuses</option>
                    <option value="pending">Pending</option>
                    <option value="ordered">Ordered</option>
                    <option value="received">Received</option>
                  </select>
                </div>
              </div>
            </div>

            {/* Orders table */}
            <div className="border rounded-lg overflow-hidden">
              <table className="w-full text-sm">
                <thead>
                  <tr className="bg-muted/50 border-b">
                    <th className="text-left px-4 py-2 font-medium text-muted-foreground">Supplier</th>
                    <th className="text-center px-4 py-2 font-medium text-muted-foreground">Status</th>
                    <th className="text-center px-4 py-2 font-medium text-muted-foreground">Lines</th>
                    <th className="text-left px-4 py-2 font-medium text-muted-foreground">Created</th>
                    <th className="text-center px-4 py-2 font-medium text-muted-foreground">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {orders.map((order) => (
                    <tr key={order.id} className="border-b last:border-b-0 hover:bg-muted/30 transition-colors cursor-pointer" onClick={() => setSelectedOrderId(order.id)}>
                      <td className="px-4 py-2">{supplierLabel(order.supplierName)}</td>
                      <td className="px-4 py-2 text-center">
                        <StatusBadge status={order.status} />
                      </td>
                      <td className="px-4 py-2 text-center">{order.lineCount ?? '—'}</td>
                      <td className="px-4 py-2 whitespace-nowrap">{formatDate(order.createdAt)}</td>
                      <td className="px-4 py-2 text-center">
                        <span className="text-muted-foreground text-xs">Click to view</span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </>
        )}

        {/* Create Order Dialog */}
        <CreateOrderDialog
          isOpen={showCreateDialog}
          onClose={() => setShowCreateDialog(false)}
          onSuccess={(orderId) => {
            toast.success('Supplier order created')
            fetchOrders()
            setSelectedOrderId(orderId)
          }}
