        {/* Order Detail Panel */}
        {selectedOrderId && (
          <OrderDetailPanel
            orderId={selectedOrderId}
            onClose={() => setSelectedOrderId(null)}
            onRefresh={fetchOrders}
          />
        )}
      </CardContent>
    </div>
  )
}

